#ifndef FUZZEDDATAPROVIDER_H
#define FUZZEDDATAPROVIDER_H

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>
#include <string>
#include <vector>

class FuzzedDataProvider {
public:
    FuzzedDataProvider(const uint8_t *data, size_t size)
        : data_ptr_(data), remaining_bytes_(size) {}

    template <typename T>
    T ConsumeIntegral() {
        static_assert(std::is_integral<T>::value, "integral required");
        T result = 0;
        size_t bytes = sizeof(T);
        if (remaining_bytes_ < bytes) bytes = remaining_bytes_;
        std::memcpy(&result, data_ptr_, bytes);
        data_ptr_ += bytes;
        remaining_bytes_ -= bytes;
        return result;
    }

    template <typename T>
    T ConsumeIntegralInRange(T min, T max) {
        static_assert(std::is_integral<T>::value, "integral required");
        if (min > max) std::abort();
        if (min == max) return min;
        using U = typename std::make_unsigned<T>::type;
        U range = static_cast<U>(max) - static_cast<U>(min);
        U result = static_cast<U>(ConsumeIntegral<U>());
        if (range != std::numeric_limits<U>::max())
            result = result % (range + 1);
        return static_cast<T>(min + result);
    }

    bool ConsumeBool() {
        return ConsumeIntegral<uint8_t>() & 1;
    }

    template <typename T>
    std::vector<T> ConsumeBytes(size_t num_bytes) {
        num_bytes = std::min(num_bytes, remaining_bytes_);
        std::vector<T> result(num_bytes);
        std::memcpy(result.data(), data_ptr_, num_bytes * sizeof(T));
        data_ptr_ += num_bytes * sizeof(T);
        remaining_bytes_ -= num_bytes * sizeof(T);
        return result;
    }

    std::string ConsumeRandomLengthString(size_t max_length = std::numeric_limits<size_t>::max()) {
        size_t len = ConsumeIntegralInRange<size_t>(0, std::min(max_length, remaining_bytes_));
        std::string result(reinterpret_cast<const char*>(data_ptr_), len);
        data_ptr_ += len;
        remaining_bytes_ -= len;
        return result;
    }

    size_t ConsumeData(void *destination, size_t num_bytes) {
        num_bytes = std::min(num_bytes, remaining_bytes_);
        std::memcpy(destination, data_ptr_, num_bytes);
        data_ptr_ += num_bytes;
        remaining_bytes_ -= num_bytes;
        return num_bytes;
    }

    size_t remaining_bytes() const { return remaining_bytes_; }

private:
    const uint8_t *data_ptr_;
    size_t remaining_bytes_;
};

#endif
